#include <iostream>
#include <vector>

#include "records.hpp"
#include "report.hpp"

// Its header needs only a forward declaration of Student.
void print_report(const std::vector<Student>& students) {
    int passed = 0;
    for (const auto& student : students) {
        std::cout << student.name << ": " << student.mark << " ";
        switch (grade_of(student)) {
            case Grade::Distinction: {
                std::cout << "distinction" << '\n';
                break;
            }
            case Grade::Pass: {
                std::cout << "pass" << '\n';
                break;
            }
            case Grade::Fail: {
                std::cout << "fail" << '\n';
                break;
            }
        }
        if (student.mark >= kPassMark) {
            ++passed;
        }
    }
    std::cout << "Passed: " << passed << " of " << static_cast<int>(students.size()) << '\n';
}
